#!/bin/sh
# generated by okoko from theme {{NAME}} - run by okoko-session and `okoko theme`.
# xfce4-terminal >= 1.1 keeps its settings in xfconf (channel xfce4-terminal), not in a
# file, and applies changes to open windows at once.
command -v xfconf-query >/dev/null || exit 0
set_() { # set_ <property> <type> <value>: update, or create when missing
    xfconf-query -c xfce4-terminal -p "$1" -s "$3" 2>/dev/null ||
        xfconf-query -c xfce4-terminal -p "$1" -n -t "$2" -s "$3"
}
set_ /font-use-system bool false
set_ /font-name string "JetBrainsMono Nerd Font 10"
set_ /misc-menubar-default bool false
set_ /misc-toolbar-default bool false
set_ /misc-borders-default bool false
set_ /scrolling-bar string TERMINAL_SCROLLBAR_NONE
set_ /scrolling-lines uint 20000
set_ /misc-cursor-shape string TERMINAL_CURSOR_SHAPE_IBEAM
set_ /misc-cursor-blinks bool true
set_ /misc-confirm-close bool false
set_ /misc-bell bool false
set_ /background-mode string TERMINAL_BACKGROUND_TRANSPARENT
set_ /background-darkness double 0.96
set_ /color-use-theme bool false
set_ /color-foreground string "{{FG}}"
set_ /color-background string "{{BG}}"
set_ /color-cursor-use-default bool false
set_ /color-cursor string "{{ACCENT2}}"
set_ /color-cursor-foreground string "{{BG}}"
set_ /color-selection-use-default bool false
set_ /color-selection string "{{BG}}"
set_ /color-selection-background string "{{ACCENT}}"
set_ /color-bold-use-default bool true
set_ /tab-activity-color string "{{WARN}}"
set_ /color-palette string "{{C0}};{{C1}};{{C2}};{{C3}};{{C4}};{{C5}};{{C6}};{{C7}};{{C8}};{{C9}};{{C10}};{{C11}};{{C12}};{{C13}};{{C14}};{{C15}}"
